struct Interval{int start;int end;};static void sort(struct Interval a[],int n){int i;int j;struct Interval v;for(i=1;i<n;i=i+1){v=a[i];j=i-1;while(j>=0&&a[j].start>v.start){a[j+1]=a[j];j=j-1;}a[j+1]=v;}}
int merge_intervals(struct Interval a[],int n,struct Interval result[]){int i;int count;sort(a,n);count=0;for(i=0;i<n;i=i+1){if(count==0||result[count-1].end<a[i].start){result[count]=a[i];count=count+1;}else if(a[i].end>result[count-1].end)result[count-1].end=a[i].end;}return count;}
int main(void){struct Interval a[4]={{1,3},{2,6},{8,10},{15,18}};struct Interval b[2]={{1,4},{4,5}};struct Interval r[4];int c;c=merge_intervals(a,4,r);if(c!=3||r[0].start!=1||r[0].end!=6||r[2].start!=15)return 1;c=merge_intervals(b,2,r);if(c!=1||r[0].start!=1||r[0].end!=5)return 2;return 42;}
